    70→        .run()
    71→        .await
    72→        .map_err(|e| anyhow::anyhow!("Query failed: {e}"))?
    73→        .data
    74→        .try_collect()
    75→        .await
    76→        .map_err(|e| anyhow::anyhow!("Failed to collect results: {e}"))
    77→}
