    79→/// Get the physical plan for a query
    80→async fn get_physical_plan(
    81→    rt: &Arc<Runtime>,
    82→    sql: &str,
    83→) -> Result<Arc<dyn ExecutionPlan>, anyhow::Error> {
    84→    let df = rt
    85→        .datafusion()
    86→        .ctx
    87→        .sql(sql)
    88→        .await
    89→        .map_err(|e| anyhow::anyhow!("Failed to create dataframe: {e}"))?;
    90→
    91→    df.create_physical_plan()
    92→        .await
    93→        .map_err(|e| anyhow::anyhow!("Failed to create physical plan: {e}"))
    94→}
