    62→#[derive(Debug, Snafu)]
    63→pub enum Error {
    64→    #[snafu(display("At least one 'partition_by' expression is required, but none were given."))]
    65→    PartitionByRequired,
    66→    #[snafu(display("Creating partition failed: {source}"))]
    67→    CreatingPartition { source: super::creator::Error },
    68→    #[snafu(display("Validating expressions failed: {source}"))]
    69→    ValidatingExpressions { source: super::expression::Error },
    70→    #[snafu(display("Failed to convert schema to DFSchema: {source}"))]
    71→    SchemaConversion { source: DataFusionError },
    72→    #[snafu(display("Expected array from partition expression, got scalar"))]
    73→    InvalidPartitionExpression,
    74→    #[snafu(display(
    75→        "Partition has {actual} values but expected {expected} (one per partition_by expression)"
    76→    ))]
    77→    PartitionValueCountMismatch { expected: usize, actual: usize },
    78→}
    79→
    80→/// Composite partition key string, used as `HashMap` key.
    81→/// For a single partition expression, this is just the encoded value (e.g., "us-east-1").
    82→/// For multiple partition expressions, this is a path-like string (e.g., "2025/10/15").
    83→pub(crate) type CompositePartitionKey = String;
    84→
    85→#[derive(Debug)]
    86→pub struct PartitionTableProvider {
    87→    creator: Arc<dyn PartitionCreator>,
    88→    /// The partition expressions. For hierarchical partitions like
    89→    /// `partition_by: [year, month]`, this contains all expressions in order.
    90→    partition_by: Vec<PartitionedBy>,
    91→    partitions: Arc<RwLock<HashMap<CompositePartitionKey, Partition>>>,
    92→    schema: SchemaRef,
    93→    insert_strategy: Arc<dyn InsertStrategy>,
    94→}
    95→
    96→impl PartitionTableProvider {
    97→    /// Checks if a filter expression contains or references any of the partition expressions.
    98→    /// This is used to identify filters that can be used for partition pruning.
    99→    fn filter_contains_any_partition_expr(
   100→        filter: &Expr,
   101→        partition_exprs: &[PartitionedBy],
   102→    ) -> bool {
   103→        use datafusion::common::tree_node::{TreeNode, TreeNodeRecursion};
   104→
   105→        let mut contains = false;
   106→        let _ = filter.apply(|expr| {
   107→            for p in partition_exprs {
   108→                if expr == &p.expression {
   109→                    contains = true;
   110→                    return Ok(TreeNodeRecursion::Stop);
   111→                }
   112→            }
   113→            Ok(TreeNodeRecursion::Continue)
   114→        });
   115→        contains
   116→    }
   117→
   118→    /// Creates a new [`PartitionTableProvider`] that partitions the data using
   119→    /// the given partition expressions.
   120→    ///
   121→    /// For hierarchical partitioning (e.g., year/month/day), pass multiple expressions
   122→    /// in the order they should be applied.
   123→    ///
   124→    /// # Errors
   125→    /// This function will return an Error when:
   126→    /// - No partition expressions are provided
   127→    /// - Partition expression validation fails
   128→    /// - Existing partitions have incompatible values
   129→    pub async fn new(
   130→        creator: Arc<dyn PartitionCreator>,
   131→        partition_by: Vec<PartitionedBy>,
   132→        schema: SchemaRef,
   133→    ) -> Result<Self, Error> {
   134→        ensure!(!partition_by.is_empty(), PartitionByRequiredSnafu);
   135→
   136→        let df_schema = DFSchema::try_from(Arc::clone(&schema)).context(SchemaConversionSnafu)?;
   137→
   138→        let partitions = creator
   139→            .infer_existing_partitions()
   140→            .await
   141→            .context(CreatingPartitionSnafu)?;
   142→
   143→        let partitions: Result<HashMap<_, _>, Error> = partitions
   144→            .into_iter()
   145→            .map(|p| {
   146→                // Validate that partition has the correct number of values
   147→                ensure!(
   148→                    p.partition_values.len() == partition_by.len(),
   149→                    PartitionValueCountMismatchSnafu {
   150→                        expected: partition_by.len(),
   151→                        actual: p.partition_values.len(),
   152→                    }
   153→                );
   154→
   155→                // Validate each partition value is compatible with its expression
   156→                for (expr, value) in partition_by.iter().zip(p.partition_values.iter()) {
   157→                    validate_scalar_compatibility(&expr.expression, value, &df_schema)
   158→                        .context(ValidatingExpressionsSnafu)?;
   159→                }
   160→
   161→                let key = encode_composite_key(&p.partition_values).map_err(|e| {
   162→                    Error::CreatingPartition {
   163→                        source: crate::creator::Error::CreatePartition {
   164→                            source: Box::new(e) as Box<dyn std::error::Error + Send + Sync>,
   165→                        },
   166→                    }
   167→                })?;
   168→                Ok((key, p))
   169→            })
   170→            .collect();
   171→
   172→        let partitions = Arc::new(RwLock::new(partitions?));
   173→
   174→        Ok(Self {
   175→            creator,
   176→            partition_by,
   177→            partitions,
   178→            schema,
   179→            insert_strategy: Arc::new(DefaultInsertStrategy),
   180→        })
   181→    }
   182→
   183→    /// Sets a custom data insertion strategy for this [`PartitionTableProvider`].
   184→    #[must_use]
   185→    pub fn with_insert_strategy(mut self, insert_strategy: Arc<dyn InsertStrategy>) -> Self {
   186→        self.insert_strategy = insert_strategy;
   187→        self
   188→    }
   189→
   190→    /// Collects all partition column references from all partition expressions.
   191→    fn all_partition_columns(&self) -> std::collections::HashSet<&datafusion::common::Column> {
   192→        self.partition_by
   193→            .iter()
   194→            .flat_map(|p| p.expression.column_refs())
   195→            .collect()
   196→    }
