   223→
   224→    async fn scan(
   225→        &self,
   226→        state: &dyn Session,
   227→        projection: Option<&Vec<usize>>,
   228→        filters: &[Expr],
   229→        limit: Option<usize>,
   230→    ) -> Result<Arc<dyn ExecutionPlan>, DataFusionError> {
   231→        // Split filters into partition filters (for pruning) and data filters (for partition scans)
   232→        // NOTE: Filters can be BOTH partition filters AND data filters for transform partitions
   233→        let partition_columns = self.all_partition_columns();
   234→
   235→        // Pre-compute column references for all filters to avoid repeated expression tree traversals
   236→        let filter_columns_cache: Vec<_> =
   237→            filters.iter().map(|filter| filter.column_refs()).collect();
   238→
   239→        // Collect partition filters (used for pruning)
   240→        // A filter can prune partitions if it involves ANY of the partition columns
   241→        let partition_filters: Vec<_> = filters
   242→            .iter()
   243→            .cloned()
   244→            .zip(filter_columns_cache.iter())
   245→            .filter_map(|(filter, filter_columns)| {
   246→                // A filter is a partition filter (for pruning) if:
   247→                // 1. It has no column references (constant expression like WHERE true), OR
   248→                // 2. All its column references are in the partition expression columns, OR
   249→                // 3. The filter directly involves any partition expression itself
   250→                if filter_columns.is_empty() {
   251→                    return Some(filter);
   252→                }
   253→
   254→                if filter_columns
   255→                    .iter()
   256→                    .all(|col| partition_columns.contains(col))
   257→                {
   258→                    return Some(filter);
   259→                }
   260→
   261→                // Check if the filter contains any partition expression
   262→                if Self::filter_contains_any_partition_expr(&filter, &self.partition_by) {
   263→                    return Some(filter);
   264→                }
   265→
   266→                None
   267→            })
   268→            .collect();
   269→
   270→        // Collect data filters (applied to partition scans)
   271→        // Exclude filters that are simple column filters matching a simple partition expression exactly
   272→        // For example, with partition_by region:
   273→        //   - WHERE region = 'us-east-1' should NOT be a data filter (partition handles it)
   274→        // But with partition_by bucket(3, user_id):
   275→        //   - WHERE user_id = 100 SHOULD be a data filter (partition only determines bucket)
   276→        let simple_partition_cols: std::collections::HashSet<_> = self
   277→            .partition_by
   278→            .iter()
   279→            .filter_map(|p| {
   280→                if let Expr::Column(col) = &p.expression {
   281→                    Some(col)
   282→                } else {
   283→                    None
   284→                }
   285→            })
   286→            .collect();
   287→
   288→        let data_filters: Vec<_> = filters
   289→            .iter()
   290→            .zip(filter_columns_cache.iter())
   291→            .filter(|(_filter, filter_cols)| {
   292→                // If this filter references only a simple partition column, exclude it
   293→                if filter_cols.len() == 1
   294→                    && let Some(col) = filter_cols.iter().next()
   295→                    && simple_partition_cols.contains(col)
   296→                {
   297→                    return false; // Exclude from data filters
   298→                }
   299→                // For all other cases (transform expressions, multiple columns, etc.), keep as data filter
   300→                true
   301→            })
   302→            .map(|(filter, _)| filter.clone())
   303→            .collect();
   304→
   305→        let partitions = self.partitions.read().await;
   306→        let mut plans = Vec::with_capacity(partitions.len());
   307→        for partition in partitions.values() {
   308→            // Check if this partition should be pruned based on ANY partition expression
   309→            let mut should_prune = false;
   310→            for (idx, partition_expr) in self.partition_by.iter().enumerate() {
   311→                // Get the partition value for this expression
   312→                let partition_value = partition.partition_values.get(idx).ok_or_else(|| {
   313→                    DataFusionError::Internal(format!("Partition missing value at index {idx}"))
   314→                })?;
   315→
   316→                if prune_partition(
   317→                    &partition_filters,
   318→                    &partition_expr.expression,
   319→                    partition_value,
   320→                    &self.schema,
   321→                )? {
   322→                    should_prune = true;
   323→                    break;
   324→                }
   325→            }
   326→
   327→            if should_prune {
   328→                continue;
   329→            }
   330→
   331→            let plan = partition
   332→                .table_provider
   333→                .scan(state, projection, &data_filters, limit)
   334→                .await?;
   335→            plans.push(plan);
   336→        }
   337→
   338→        let plan = match plans {
   339→            plans if plans.is_empty() => {
   340→                let projected_schema = project_schema(&self.schema, projection)?;
   341→                return Ok(Arc::new(EmptyExec::new(projected_schema)));
   342→            }
   343→            mut plans if plans.len() == 1 => plans.pop().ok_or_else(|| {
   344→                DataFusionError::Execution("expected an ExecutionPlan".to_string())
   345→            })?,
   346→            plans => Arc::new(PartitionedUnionExec::try_new(plans)?),
   347→        };
   348→
   349→        if let Some(limit) = limit {
   350→            return Ok(Arc::new(GlobalLimitExec::new(plan, limit, None)));
   351→        }
   352→
   353→        Ok(plan)
   354→    }
   355→
   356→    async fn insert_into(
   357→        &self,
   358→        _state: &dyn Session,
   359→        input: Arc<dyn ExecutionPlan>,
   360→        insert_op: InsertOp,
   361→    ) -> Result<Arc<dyn ExecutionPlan>, DataFusionError> {
   362→        let ctx = PartitionContext {
