   375→/// Implement `DeletionTableProvider` to support retention checks and delete operations
   376→/// on partitioned tables. Deletion is applied to all partitions.
   377→#[async_trait]
   378→impl DeletionTableProvider for PartitionTableProvider {
   379→    async fn delete_from(
   380→        &self,
   381→        state: &dyn Session,
   382→        filters: &[Expr],
   383→    ) -> datafusion::error::Result<Arc<dyn ExecutionPlan>> {
   384→        // Collect all partitions that need deletion
   385→        let partitions = self.partitions.read().await;
   386→        let partition_list: Vec<_> = partitions.values().cloned().collect();
   387→        drop(partitions);
   388→
   389→        // Create a deletion sink that will iterate over all partitions
   390→        let deletion_sink = Arc::new(PartitionedDeletionSink::new(
   391→            partition_list,
   392→            filters.to_vec(),
   393→            state.task_ctx(),
   394→        ));
   395→
   396→        Ok(Arc::new(DeletionExec::new(deletion_sink, &self.schema)))
   397→    }
   398→}
   399→
   400→/// A deletion sink that applies deletion filters to all partitions in a partitioned table.
   401→struct PartitionedDeletionSink {
   402→    partitions: Vec<Partition>,
   403→    filters: Vec<Expr>,
   404→    task_ctx: Arc<TaskContext>,
   405→}
   406→
   407→impl PartitionedDeletionSink {
   408→    fn new(partitions: Vec<Partition>, filters: Vec<Expr>, task_ctx: Arc<TaskContext>) -> Self {
   409→        Self {
   410→            partitions,
   411→            filters,
   412→            task_ctx,
   413→        }
   414→    }
   415→}
   416→
   417→#[async_trait]
   418→impl DeletionSink for PartitionedDeletionSink {
   419→    async fn delete_from(&self) -> Result<u64, Box<dyn std::error::Error + Send + Sync>> {
   420→        let mut total_deleted = 0u64;
   421→
   422→        for partition in &self.partitions {
   423→            // Try to downcast the partition's table provider to DeletionTableProvider
   424→            // The partition's table provider might be a CayenneTableProvider or similar
   425→            // that implements DeletionTableProvider
   426→            let deletion_provider = data_components::delete::get_deletion_provider(Arc::clone(
   427→                &partition.table_provider,
   428→            ));
   429→
   430→            if let Some(deletion_provider) = deletion_provider {
   431→                // Create a simple session state for executing the deletion
   432→                let session_ctx = datafusion::execution::context::SessionContext::new();
   433→                let state = session_ctx.state();
   434→
   435→                // Execute deletion on this partition
   436→                let plan = DeletionTableProvider::delete_from(
   437→                    deletion_provider.as_ref(),
   438→                    &state,
   439→                    &self.filters,
   440→                )
   441→                .await?;
   442→
   443→                // Execute the deletion plan
   444→                let results = collect(plan, Arc::clone(&self.task_ctx)).await?;
   445→
   446→                // Extract the count from results
   447→                for batch in results {
   448→                    if let Some(count_col) = batch.column_by_name("count")
   449→                        && let Some(uint_array) = count_col.as_any().downcast_ref::<UInt64Array>()
   450→                    {
   451→                        for i in 0..uint_array.len() {
   452→                            if !uint_array.is_null(i) {
   453→                                total_deleted += uint_array.value(i);
   454→                            }
   455→                        }
   456→                    }
   457→                }
   458→            } else {
   459→                tracing::warn!(
   460→                    partition_values = ?partition.partition_values,
   461→                    "Partition table provider does not support deletion. Skipping."
   462→                );
   463→            }
   464→        }
   465→
   466→        Ok(total_deleted)
   467→    }
   468→}
