/// Test that `hash_index: enabled` is correctly propagated to every Arrow partition.
///
/// We verify correctness by confirming:
/// 1. The dataset loads successfully with `hash_index: enabled` + `primary_key` set (prior to the
///    fix, the option was silently dropped; a misconfigured option would prevent loading).
/// 2. All 10 rows remain queryable via a full scan (data integrity).
/// 3. Filtered queries return the correct subset (the hash index did not corrupt the table).
///
/// Note: point lookups via the `PartitionTableProvider` do not currently use the per-partition
/// hash index — that path is tested separately in `hash_index.rs` for the plain Arrow accelerator.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn test_arrow_partition_hash_index() -> Result<(), anyhow::Error> {
    let _tracing = crate::init_tracing(Some("integration=debug,info"));

    test_request_context()
        .scope(async {
            let test_file = std::env::current_dir()
                .map_err(|e| anyhow::anyhow!("Failed to get current directory: {e}"))?
                .join("tests/acceleration/data/partition_test.csv");

            crate::configure_test_datafusion();

            let mut params = HashMap::new();
            params.insert("hash_index".to_string(), "enabled".to_string());

            let dataset = make_dataset(
                "arrow_partition_hash_test",
                &test_file,
                vec![PartitionedBy {
                    name: "expr0".to_string(),
                    expression: "bucket(3, id)".to_string(),
                }],
                params,
                Some("id".to_string()),
            );

            let app = AppBuilder::new("test_arrow_partition_hash_index")
                .with_dataset(dataset)
                .build();

            let rt = Arc::new(Runtime::builder().with_app(app).build().await);

            tokio::select! {
                () = tokio::time::sleep(std::time::Duration::from_secs(30)) => {
                    return Err(anyhow::Error::msg("Timeout waiting for components to load"));
                }
                () = Arc::clone(&rt).load_components() => {}
            }

            runtime_ready_check(&rt).await;

            // All rows should be accessible — verifies the option was accepted and data loaded.
            let result =
                run_query(&rt, "SELECT * FROM arrow_partition_hash_test ORDER BY id").await?;
            let total: usize = result.iter().map(RecordBatch::num_rows).sum();
            assert_eq!(total, 10, "Expected 10 rows total");

            // Filtered query across multiple partitions — data must be intact.
            let result = run_query(
                &rt,
                "SELECT id, name FROM arrow_partition_hash_test WHERE score > 90 ORDER BY id",
            )
            .await?;
            let expected = [
                "+----+--------------+",
                "| id | name         |",
                "+----+--------------+",
                "| 2  | Jane Smith   |",
                "| 6  | Sarah Wilson |",
                "| 10 | Anna Garcia  |",
                "+----+--------------+",
            ];
            assert_batches_eq!(&expected, &result);

            Ok(())
        })
        .await
}

